export type PokemonType =
  | 'bug'
  | 'dark'
  | 'dragon'
  | 'electric'
  | 'fairy'
  | 'fighting'
  | 'fire'
  | 'flying'
  | 'ghost'
  | 'grass'
  | 'ground'
  | 'ice'
  | 'normal'
  | 'poison'
  | 'psychic'
  | 'rock'
  | 'steel'
  | 'water'

export type PokemonRegion =
  | 'Alola'
  | 'Galar'
  | 'Hisui'
  | 'Hoenn'
  | 'Johto'
  | 'Kalos'
  | 'Kanto'
  | 'Paldea'
  | 'Sinnoh'
  | 'Unova'

export type PokemonColor =
  | 'black'
  | 'blue'
  | 'brown'
  | 'gray'
  | 'green'
  | 'pink'
  | 'purple'
  | 'red'
  | 'white'
  | 'yellow'

export interface Pokemon {
  id: number
  name: string
  region: PokemonRegion
  color: PokemonColor
  types: PokemonType[]
  heightM: number
  weightKg: number
  hp: number
  attack: number
  defense: number
  specialAttack: number
  specialDefense: number
  speed: number
  evolutionStage: 1 | 2 | 3
  evolutionLineStages: 1 | 2 | 3
  evolvesByStone: boolean
  isStarter: boolean
  isLegendary: boolean
  isMythical: boolean
  sprite: string
  shinySprite?: string
}

export const getShinySpriteUrl = (pokemonId: number): string =>
  `/sprites/shiny/${pokemonId}.png`

